-- security_nov22: shared guard, included at the top of every migration here (01-04). Safe to run many times.
-- pb_sec.guard(tag, function, md5): refuses (and so rolls the whole migration back) when the live definition of a
-- function we replace is not the one read on Nov 21 2026. When it matches, the live definition is saved first in
-- pb_sec.fn_backup, so the undo files put back the exact text that was live (no copy typed by hand).
-- Running a migration a second time: the backup row is already there, so it goes through again.
create schema if not exists pb_sec;
revoke all on schema pb_sec from public;
revoke all on schema pb_sec from anon, authenticated;
create table if not exists pb_sec.fn_backup (
  tag      text not null,          -- which migration (nov22_01 ...)
  sig      text not null,          -- regprocedure text, e.g. public.pb_session_gate()
  def      text not null,          -- pg_get_functiondef() as it was live
  md5      text not null,
  saved_at timestamptz not null default now(),
  primary key (tag, sig)
);
alter table pb_sec.fn_backup enable row level security;
revoke all on table pb_sec.fn_backup from public;
revoke all on table pb_sec.fn_backup from anon, authenticated;

create or replace function pb_sec.guard(p_tag text, p_sig text, p_md5 text) returns void
language plpgsql set search_path = '' as $f$
declare v_def text; v_md5 text;
begin
  v_def := pg_get_functiondef(p_sig::regprocedure);
  v_md5 := md5(v_def);
  if v_md5 = p_md5 then
    insert into pb_sec.fn_backup (tag, sig, def, md5) values (p_tag, p_sig, v_def, v_md5) on conflict (tag, sig) do nothing;
    return;
  end if;
  if exists (select 1 from pb_sec.fn_backup b where b.tag = p_tag and b.sig = p_sig) then return; end if; -- this migration ran before
  -- (throwaway local test database only: the stand-in functions there are not the live text)
  if current_setting('pb_sec.guard', true) = 'skip-local-test' then
    insert into pb_sec.fn_backup (tag, sig, def, md5) values (p_tag, p_sig, v_def, v_md5) on conflict (tag, sig) do nothing;
    return;
  end if;
  raise exception 'pb_sec: % changed on live since Nov 21 2026 (md5 % , expected %). Nothing was applied. Re-read it and rebase this migration.', p_sig, v_md5, p_md5;
end $f$;
revoke all on function pb_sec.guard(text, text, text) from public;
revoke all on function pb_sec.guard(text, text, text) from anon, authenticated;

-- undo helper: puts back every function a migration replaced, exactly as it was live
create or replace function pb_sec.restore(p_tag text) returns integer
language plpgsql set search_path = '' as $f$
declare r record; n integer := 0;
begin
  for r in select b.sig, b.def from pb_sec.fn_backup b where b.tag = p_tag order by b.sig loop
    execute r.def; n := n + 1;
  end loop;
  delete from pb_sec.fn_backup where tag = p_tag;
  return n;
end $f$;
revoke all on function pb_sec.restore(text) from public;
revoke all on function pb_sec.restore(text) from anon, authenticated;

-- security_nov22 04 (review finding 4, LOW): the wrong-join-code brake counts per caller, not app-wide.
-- Before: pb_onboard.braked() = 30 wrong codes in 10 minutes from ANYONE. pb_onboard_peek works signed out, so one
-- person typing junk could stop every company's crews joining by typed code for 10 minutes.
-- After: each wrong code is filed with a caller key: a signed-in caller by a hash of their login; a signed-out caller
-- (pb_onboard_peek) by a keyed hash of their IP (HMAC-SHA256 with a random key kept in the database, first 32 hex, the
-- way the website's trial form keys its limit; the IP itself is never stored); the crew-join edge function by the key it
-- sends in the x-pb-caller header (an HMAC of the person's IP made in the function: edge/crew-join). The brake is
--   30 wrong codes in 10 minutes from the same caller (the old number, now per caller), or
--   600 wrong codes in 10 minutes from everyone together (backstop against many IPs).
-- A caller with no key (no IP header reached the database) shares one bucket with the old limit of 30: never worse than
-- today. Rows are kept 1 day, as before. After applying, check that keys arrive (NOTES: "after 04").
-- Changes pb_onboard.braked() and pb_onboard.miss(); pb_onboard.find() and the callers are unchanged.
-- Run as postgres, in one transaction (the whole file). Safe to run twice. Undo: undo/99_undo_04.sql.

select pb_sec.guard('nov22_04', 'pb_onboard.braked()', '3e997a1374454a667b67997b7843a410');
select pb_sec.guard('nov22_04', 'pb_onboard.miss(text)', '6a784f2b22b27924a4661aeb14ab2cd6');

alter table pb_onboard.misses add column if not exists who text;
create index if not exists misses_who_at on pb_onboard.misses (who, at);

create table if not exists pb_onboard.caller_salt (id integer primary key default 1 check (id = 1), k bytea not null);
alter table pb_onboard.caller_salt enable row level security;
revoke all on table pb_onboard.caller_salt from public;
revoke all on table pb_onboard.caller_salt from anon, authenticated;
insert into pb_onboard.caller_salt (id, k) values (1, extensions.gen_random_bytes(32)) on conflict (id) do nothing;

-- the caller's key for the brake (null: none could be made)
create or replace function pb_onboard.caller() returns text
language plpgsql stable security definer set search_path = '' as $f$
declare h jsonb; c jsonb; ip text; v_role text; v_sub text;
begin
  begin c := nullif(current_setting('request.jwt.claims', true), '')::jsonb; exception when others then c := null; end;
  begin h := nullif(current_setting('request.headers', true), '')::jsonb; exception when others then h := null; end;
  v_role := coalesce(c->>'role', ''); v_sub := c->>'sub';
  if v_role = 'authenticated' and v_sub ~ '^[0-9a-f-]{36}$' then return 'u:' || left(md5(v_sub), 32); end if;
  if v_role = 'service_role' then  -- only the service role may name the caller (crew-join)
    ip := lower(btrim(coalesce(h->>'x-pb-caller', '')));
    return case when ip ~ '^[0-9a-f]{16,64}$' then 'e:' || left(ip, 32) else 'e:' end; -- 'e:' alone: crew-join before its update (one bucket, as today)
  end if;
  ip := coalesce(nullif(btrim(h->>'cf-connecting-ip'), ''),
                 nullif(btrim(split_part(coalesce(h->>'x-forwarded-for', ''), ',', 1)), ''),
                 nullif(btrim(h->>'x-real-ip'), ''));
  if ip is null then return null; end if;
  return 'i:' || left(encode(extensions.hmac(convert_to(left(ip, 64), 'UTF8'), (select s.k from pb_onboard.caller_salt s where s.id = 1), 'sha256'), 'hex'), 32);
end $f$;
revoke all on function pb_onboard.caller() from public;
revoke all on function pb_onboard.caller() from anon, authenticated;

CREATE OR REPLACE FUNCTION pb_onboard.braked()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  -- security_nov22 04: per caller (30 in 10 minutes, the old number), plus a whole-app backstop (600 in 10 minutes)
  select (select count(*) from pb_onboard.misses m where m.at > now() - interval '10 minutes') >= 600
      or (select count(*) from pb_onboard.misses m where m.at > now() - interval '10 minutes' and m.who is not distinct from pb_onboard.caller()) >= 30
$function$;

CREATE OR REPLACE FUNCTION pb_onboard.miss(p_kind text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  delete from pb_onboard.misses where at < now() - interval '1 day';
  insert into pb_onboard.misses (kind, who) values (left(p_kind, 20), pb_onboard.caller()); -- security_nov22 04: who (a key, never the IP)
$function$;

-- security_nov22 04 test: the wrong-code brake counts per caller, with a whole-app backstop. Ends with 'RESULT: ...'.
-- who: 'anon:<ip>' (signed out, from that IP), 'anon:' (no IP header), 'user:<uuid>', 'svc:<key>' (crew-join), 'svc:' (no key)
create function pg_temp.s4_who(p_who text) returns void language plpgsql as $f$
declare k text := split_part(p_who, ':', 1); v text := substr(p_who, length(k) + 2);
begin
  if k = 'anon' then
    perform set_config('request.jwt.claims', '{"role":"anon"}', true);
    perform set_config('request.headers', case when v = '' then '{}' else jsonb_build_object('x-forwarded-for', v || ', 10.0.0.1', 'x-pb-caller', 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa')::text end, true);
  elsif k = 'user' then
    perform set_config('request.jwt.claims', jsonb_build_object('role', 'authenticated', 'sub', v)::text, true);
    perform set_config('request.headers', '{"x-forwarded-for":"198.51.100.7"}', true);
  else
    perform set_config('request.jwt.claims', '{"role":"service_role"}', true);
    perform set_config('request.headers', case when v = '' then '{}' else jsonb_build_object('x-pb-caller', v)::text end, true);
  end if;
end $f$;
-- one wrong typed code from p_who: 'none' (not braked, no match) or 'busy'
create function pg_temp.s4_try(p_who text) returns text language plpgsql as $f$
declare v uuid;
begin perform pg_temp.s4_who(p_who); v := pb_onboard.find(null, 'QQ' || lpad((floor(random() * 9999))::int::text, 4, '0'), 'join');
  return coalesce(v::text, 'none');
exception when others then return case when sqlerrm like 'pb:busy%' then 'busy' else 'ERR ' || sqlerrm end; end $f$;
create function pg_temp.s4_many(p_who text, p_n integer) returns text language plpgsql as $f$
declare i integer; r text; last text;
begin for i in 1..p_n loop r := pg_temp.s4_try(p_who); last := r; if r <> 'none' then return r || '@' || i; end if; end loop; return last; end $f$;

do $test$
declare
  pass integer; fail integer; fails text; notes text := ''; u uuid := gen_random_uuid(); x text; base integer; k1 text; k2 text;
begin
  create temp table t_chk (i serial, name text, ok boolean, got text) on commit drop;
  -- start from a quiet table (inside this rolled-back test only)
  delete from pb_onboard.misses;

  x := pg_temp.s4_many('anon:203.0.113.5', 30);
  insert into t_chk (name, ok, got) values ('4a 30 wrong codes from one phone: none braked yet', x = 'none', x);
  x := pg_temp.s4_try('anon:203.0.113.5');
  insert into t_chk (name, ok, got) values ('4b 31st from that phone: braked (pb:busy)', x = 'busy', x);
  x := pg_temp.s4_try('anon:203.0.113.99');
  insert into t_chk (name, ok, got) values ('4c another phone (IP) at the same time: NOT braked (was braked app-wide before)', x = 'none', x);
  x := pg_temp.s4_try('user:' || u);
  insert into t_chk (name, ok, got) values ('4d a signed-in person: not braked by the stranger', x = 'none', x);
  x := pg_temp.s4_try('svc:0123456789abcdef0123456789abcdef');
  insert into t_chk (name, ok, got) values ('4e crew-join for another phone (its key): not braked', x = 'none', x);
  -- spoofing: a signed-out caller cannot pick its own key with x-pb-caller (only the service role may)
  perform pg_temp.s4_who('anon:203.0.113.5'); k1 := pb_onboard.caller();
  perform pg_temp.s4_who('svc:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa'); k2 := pb_onboard.caller();
  insert into t_chk (name, ok, got) values ('4f x-pb-caller from a signed-out caller is ignored (key = its IP hash)', k1 like 'i:%' and k1 <> 'e:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa' and k2 = 'e:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa', k1 || ' | ' || k2);
  insert into t_chk (name, ok, got) select '4g the IP is never stored (only a 32-hex keyed hash)',
    not exists (select 1 from pb_onboard.misses where who like '%203.0.113%' or who like '%198.51%') and exists (select 1 from pb_onboard.misses where who ~ '^i:[0-9a-f]{32}$'), '';
  -- a signed-in caller is keyed by login, not IP
  perform pg_temp.s4_who('user:' || u); k1 := pb_onboard.caller();
  insert into t_chk (name, ok, got) values ('4h signed-in key is a hash of the login', k1 = 'u:' || md5(u::text), k1);
  -- no IP header at all: one shared bucket with the old limit (never worse than before)
  x := pg_temp.s4_many('anon:', 30) || '/' || pg_temp.s4_try('anon:');
  insert into t_chk (name, ok, got) values ('4i callers with no IP header share the old limit (30)', x = 'none/busy', x);
  x := pg_temp.s4_try('anon:203.0.113.77');
  insert into t_chk (name, ok, got) values ('4j ... which does not brake callers that have an IP', x = 'none', x);
  x := pg_temp.s4_many('svc:', 30) || '/' || pg_temp.s4_try('svc:');
  insert into t_chk (name, ok, got) values ('4k crew-join without a key: its own bucket of 30', x = 'none/busy', x);
  -- whole-app backstop: many IPs together
  select count(*) into base from pb_onboard.misses where at > now() - interval '10 minutes';
  insert into pb_onboard.misses (at, kind, who) select now(), 'code', 'i:' || md5(g::text) from generate_series(1, 600 - base) g;
  x := pg_temp.s4_try('anon:192.0.2.1');
  insert into t_chk (name, ok, got) values ('4l 600 wrong codes in 10 minutes from everyone: everyone braked (backstop)', x = 'busy', x);
  update pb_onboard.misses set at = now() - interval '11 minutes';
  x := pg_temp.s4_try('anon:203.0.113.5');
  insert into t_chk (name, ok, got) values ('4m 10 minutes later: free again', x = 'none', x);
  insert into t_chk (name, ok, got) values ('4n caller() and the key table are not reachable from the API',
    not has_function_privilege('anon', 'pb_onboard.caller()', 'execute') and not has_function_privilege('authenticated', 'pb_onboard.caller()', 'execute')
    and not has_table_privilege('anon', 'pb_onboard.caller_salt', 'select') and not has_table_privilege('authenticated', 'pb_onboard.caller_salt', 'select'), '');
  insert into t_chk (name, ok, got) select '4o one key, 32 random bytes', (select count(*) = 1 and min(length(k)) = 32 from pb_onboard.caller_salt), '';
  insert into t_chk (name, ok, got) select '4p both live functions saved for undo', (select count(*) from pb_sec.fn_backup where fn_backup.tag = 'nov22_04') = 2, '';

  select count(*) filter (where ok), count(*) filter (where ok is not true), coalesce(string_agg(name || ' [got: ' || coalesce(got, 'null') || ']', ' ; ' order by i) filter (where ok is not true), '') into pass, fail, fails from t_chk;
  raise exception 'RESULT: % pass, % fail% %', pass, fail, case when fail > 0 then ' | FAILED: ' || fails else '' end, notes;
end $test$;

